@Test
public void testRun() throws IOException {
    TestServer server = TestServer.runSimpleServer(4444, 5);
    try {
        String tmp = System.getProperty("java.io.tmpdir");
        File file;
        if (tmp != null) {
            file = new File(tmp, "retrieverTest");
        } else {
            file = new File("retrieverTest");
        }
        file.deleteOnExit();
        Retriever r;
        try {
            message = "";
            status = "";
            // Test 301 redirect
            r = new Retriever(file, "http://localhost:" + server.getPort() + "/glassfishv3/moved.zip", "http://localhost:" + server.getPort() + "/", "http://localhost:" + server.getPort() + "/glassfish/v3-prelude/release/glassfish-v3-prelude-ml.zip", this, "glassfishv3");
            r.run();
            System.out.println("message=" + message);
            System.out.println("status=" + status);
            assert message.startsWith("Download & Install completed in") : message;
            assert status.equals("") : status;
        } finally {
            deleteJunk(file);
        }
        try {
            message = "";
            status = "";
            // Test indirect download location correct
            r = new Retriever(file, "http://localhost:" + server.getPort() + "/glassfishv3/preludezipfilename.txt", "http://localhost:" + server.getPort() + "/", "http://localhost:" + server.getPort() + "/glassfish/v3-prelude/release/glassfish-v3-prelude-ml.zip", this, "glassfishv3");
            r.run();
            System.out.println("message=" + message);
            System.out.println("status=" + status);
            assert message.startsWith("Download & Install completed in") : message;
            assert status.equals("") : status;
        } finally {
            deleteJunk(file);
        }
        try {
            message = "";
            status = "";
            // bad location source url -- falls back to the default url
            r = new Retriever(file, "http://localhost:" + server.getPort() + "/glassfishv3/preludezipfilename.tx", "http://localhost:" + server.getPort() + "/", "http://localhost:" + server.getPort() + "/glassfish/v3-prelude/release/glassfish-v3-prelude-ml.zip", this, "glassfishv3");
            r.run();
            System.out.println("message=" + message);
            System.out.println("status=" + status);
            assert message.startsWith("Download & Install completed in") : message;
            assert status.equals("") : status;
        } finally {
            deleteJunk(file);
        }
    } finally {
        server.cancel();
    }
}

/**
 * Test of getDurationString method, of class Retriever.
 */
@Test
public void testGetDurationString() {
    System.out.println("getDurationString");
    int time = 0;
    String expResult = "no time at all";
    String result = Retriever.getDurationString(time);
    assertEquals(expResult, result);
    time = -50;
    expResult = "an eternity";
    result = Retriever.getDurationString(time);
    assertEquals(expResult, result);
    time = 7;
    expResult = "7 ms";
    result = Retriever.getDurationString(time);
    assertEquals(expResult, result);
    time = 77;
    expResult = "77 ms";
    result = Retriever.getDurationString(time);
    assertEquals(expResult, result);
    time = 777;
    expResult = "777 ms";
    result = Retriever.getDurationString(time);
    assertEquals(expResult, result);
    time = 1100;
    expResult = "1 second";
    result = Retriever.getDurationString(time);
