            System.out.println("isRunning " + host + ":4848");
            poundOnIt(host, port, true);
        } finally {
            ss.close();
        }
    } else {
        System.out.println("isRunning " + host + ":4848");
        poundOnIt(host, 4848, NetUtils.isPortListeningRemote(host, 4848, NetUtils.PORT_CHECK_TIMEOUT));
    }
