@Test
@SuppressWarnings("SleepWhileInLoop")
public void startDASTest() {
    String javaArgsProperty = getGlassFishProperty(GFPROP_JAVA_ARGS);
    String glassFishArgsProperty = getGlassFishProperty(GFPROP_GLASSFISH_ARGS);
    List<String> javaArgs = javaArgsProperty != null ? Arrays.asList(javaArgsProperty.split(" +")) : new ArrayList<String>();
    List<String> glassFishArgs = glassFishArgsProperty != null ? Arrays.asList(glassFishArgsProperty.split(" +")) : new ArrayList<String>();
    StartupArgsEntity startupArgs = new StartupArgsEntity(glassFishArgs, javaArgs, new HashMap<String, String>(), getJdkProperty(JDKPROP_HOME));
    GlassFishServer server = glassFishServer();
    ResultProcess result = ServerTasks.startServer(server, startupArgs);
    ValueProcess process = result.getValue();
    StreamLinesList stdOut = new StreamLinesList(process.getProcess().getInputStream());
    boolean exit = false;
    boolean started = false;
    boolean shutdownOnError = false;
    int emptyCycles = 0;
    while (!exit && emptyCycles++ < 10) {
        String line;
        while ((line = stdOut.getNext()) != null) {
            Matcher startedMessageMatcher = STARTED_MESSAGE_PATTERN.matcher(line);
            Matcher shutdownMessageMatcher = SHUTDOWN_MESSAGE_PATTERN.matcher(line);
            if (startedMessageMatcher.matches()) {
                started = true;
                exit = true;
            }
            if (shutdownMessageMatcher.matches()) {
                shutdownOnError = true;
            }
            System.out.println("STDOUT: " + line);
            emptyCycles = 0;
        }
        try {
            Thread.sleep(1000);
        } catch (InterruptedException ie) {
            fail("FetchLogData command execution failed: " + ie.getMessage());
        }
    }
    assertNotNull(result.getValue());
    assertTrue(started);
    if (shutdownOnError) {
        System.out.println("GlassFish exited on error!");
    }
}

