 */
@Test
public void testStringExactMatch() {
    StringPrefixTree<Integer> pt = new StringPrefixTree<Integer>(true);
    pt.add("ABC", 1);
    pt.add("ABCDE", 2);
    pt.add("ABE", 3);
    Integer v1 = pt.match("ABC");
    Integer v2 = pt.match("ABCDE");
    Integer v3 = pt.match("ABE");
    Integer v4 = pt.match("ABCD");
