@Test
public void testSimpleRename() throws Exception {
    MockLSP.createServer = () -> new TestLanguageServer();
    MockServices.setServices(MimeDataProviderImpl.class, MockMimeResolver.class, RootMimeDataProviderImpl.class);
    FileObject folder = FileUtil.createMemoryFileSystem().getRoot().createFolder("myfolder");
    FileObject file1 = createFile(folder, "data1.mock-txt");
    try (OutputStream out = file1.getOutputStream()) {
        out.write(("  test  other\n" + "  other test\n").getBytes(StandardCharsets.UTF_8));
    }
    FileObject file2 = createFile(folder, "data2.mock-txt");
    try (OutputStream out = file2.getOutputStream()) {
        out.write(("  2test  other\n" + "  2other test\n").getBytes(StandardCharsets.UTF_8));
    }
    String uri = Utils.toURI(file1);
    LSPBindings bindings = LSPBindings.getBindings(file1);
    RenameParams renameParams = new RenameParams(new TextDocumentIdentifier(uri), new Position(1, 8), "newName");
    List<Function<RenameParams, WorkspaceEdit>> renameFunctions = Arrays.asList(params -> {
        assertEquals(uri, params.getTextDocument().getUri());
        assertEquals("newName", params.getNewName());
        WorkspaceEdit result = new WorkspaceEdit();
        String file1URI = params.getTextDocument().getUri();
        TextDocumentEdit file1Edits = new TextDocumentEdit(new VersionedTextDocumentIdentifier(file1URI, -1), Arrays.asList(new TextEdit(new Range(new Position(0, 2), new Position(0, 6)), "newName"), new TextEdit(new Range(new Position(1, 8), new Position(1, 12)), "newName")));
        String file2URI = file1URI.replace("data1", "data2");
        TextDocumentEdit file2Edits = new TextDocumentEdit(new VersionedTextDocumentIdentifier(file2URI, -1), Arrays.asList(new TextEdit(new Range(new Position(0, 3), new Position(0, 7)), "newName"), new TextEdit(new Range(new Position(1, 9), new Position(1, 13)), "newName")));
        result.setDocumentChanges(Arrays.asList(Either.forLeft(file1Edits), Either.forLeft(file2Edits)));
        return result;
    }, params -> {
        assertEquals(uri, params.getTextDocument().getUri());
        assertEquals("newName", params.getNewName());
        WorkspaceEdit result = new WorkspaceEdit();
        Map<String, List<TextEdit>> file2Edits = new HashMap<>();
        String file1URI = params.getTextDocument().getUri();
        file2Edits.put(file1URI, Arrays.asList(new TextEdit(new Range(new Position(0, 2), new Position(0, 6)), "newName"), new TextEdit(new Range(new Position(1, 8), new Position(1, 12)), "newName")));
        String file2URI = file1URI.replace("data1", "data2");
        file2Edits.put(file2URI, Arrays.asList(new TextEdit(new Range(new Position(0, 3), new Position(0, 7)), "newName"), new TextEdit(new Range(new Position(1, 9), new Position(1, 13)), "newName")));
        result.setChanges(file2Edits);
        return result;
    });
    for (Function<RenameParams, WorkspaceEdit> renameFunc : renameFunctions) {
        renameFunction = renameFunc;
        RenameRefactoring refactoring = new RenameRefactoring(Lookups.fixed(bindings, renameParams));
        RefactoringSession session = RefactoringSession.create("test rename");
        assertNull(refactoring.checkParameters());
        assertNull(refactoring.preCheck());
        assertNull(refactoring.prepare(session));
        Set<String> elements = new HashSet<>();
        for (RefactoringElement re : session.getRefactoringElements()) {
            RefactoringElementImplementation impl = APIAccessor.DEFAULT.getRefactoringElementImplementation(re);
            Method getNewFileContent = impl.getClass().getDeclaredMethod("getNewFileContent");
            getNewFileContent.setAccessible(true);
            String newFileContent = (String) getNewFileContent.invoke(impl);
            String element = positionToString(re.getPosition().getBegin()) + "-" + positionToString(re.getPosition().getEnd()) + ":" + newFileContent;
            elements.add(element);
        }
        Set<String> expectedElements = new HashSet<>(Arrays.asList("1:9-1:13:  2newName  other\n" + "  2other newName\n", "0:3-0:7:  2newName  other\n" + "  2other newName\n", "1:8-1:12:  newName  other\n" + "  other newName\n", "0:2-0:6:  newName  other\n" + "  other newName\n"));
        assertEquals(expectedElements, elements);
        session.doRefactoring(true);
        assertFile(file1, "  newName  other\n" + "  other newName\n");
        assertFile(file2, "  2newName  other\n" + "  2other newName\n");
        session.undoRefactoring(true);
        assertFile(file1, "  test  other\n" + "  other test\n");
        assertFile(file2, "  2test  other\n" + "  2other test\n");
    }
}

