    Problem problem = refactoring.prepare(session);
    assertNull(problem2String(problem), problem);
    Set<String> elements = new HashSet<>();
    for (RefactoringElement re : session.getRefactoringElements()) {
        RefactoringElementImplementation impl = APIAccessor.DEFAULT.getRefactoringElementImplementation(re);
        if (impl instanceof DiffElement) {
            Method getNewFileContent = impl.getClass().getDeclaredMethod("getNewFileContent");
            getNewFileContent.setAccessible(true);
            String newFileContent = (String) getNewFileContent.invoke(impl);
            String element = positionToString(re.getPosition().getBegin()) + "-" + positionToString(re.getPosition().getEnd()) + ":" + newFileContent;
            elements.add(element);
        } else if (impl instanceof LSPRenameFile || impl instanceof LSPDeleteFile || impl instanceof LSPCreateFile) {
            elements.add(impl.toString());
        } else {
            fail("Unknown element class: " + impl.getClass());
        }
    }
    Set<String> expectedElements = new HashSet<>(Arrays.asList("data2.mock-txt=>", "data1.mock-txt=>data1a.mock-txt", "1:8-1:12:  newName  other\n" + "  other newName\n", "0:2-0:6:  newName  other\n" + "  other newName\n", "=>data3.mock-txt(newName content\n)"));
    assertEquals(expectedElements, elements);
    session.doRefactoring(true);
    assertEquals("data1a.mock-txt", file1.getNameExt());
    assertFile(file1, "  newName  other\n" + "  other newName\n");
    assertFalse(file2.isValid());
    //Backup facility does not handle non file:// URLs:
    //        session.undoRefactoring(true);
    //
    //        assertFile(file1, "  test  other\n" +
    //                          "  other test\n");
    //        assertFile(file2, "  2test  other\n" +
    //                          "  2other test\n");
}

@Test
public void testOpenClose() throws Exception {
    MockLSP.createServer = () -> new TestLanguageServer();
    MockServices.setServices(MimeDataProviderImpl.class, MockMimeResolver.class);
    new TextDocumentSyncServerCapabilityHandler.Init().run();
    FileObject folder = FileUtil.createMemoryFileSystem().getRoot().createFolder("myfolder");
    FileObject file = folder.createData("data.mock-txt");
    EditorCookie ec = file.getLookup().lookup(EditorCookie.class);
    ((CloneableEditorSupport) ec).setMIMEType(MIME_TYPE);
    Document doc = ec.openDocument();
    JEditorPane pane = new JEditorPane() {

        @Override
        public boolean isFocusOwner() {
            return true;
        }
    };
    pane.setDocument(doc);
    String uri = Utils.toURI(file);
    SwingUtilities.invokeLater(() -> {
        EditorApiPackageAccessor.get().register(pane);
    });
    assertEvents("didOpen: " + uri + "/" + MIME_TYPE + "/0/");
    NbDocument.runAtomic((StyledDocument) doc, () -> {
        try {
            doc.insertString(0, "text", null);
        } catch (BadLocationException ex) {
            throw new IllegalStateException(ex);
        }
    });
    assertEvents("didChange: " + uri + "/1/[0:0-0:0 => text]");
    NbDocument.runAtomic((StyledDocument) doc, () -> {
        try {
            doc.remove(2, 1);
        } catch (BadLocationException ex) {
            throw new IllegalStateException(ex);
        }
    });
    assertEvents("didChange: " + uri + "/2/[0:2-0:3 => ]");
    assertTrue(DataObject.getRegistry().getModifiedSet().contains(DataObject.find(file)));
    //TODO: send save event:
    //        LifecycleManager.getDefault().saveAll();
    //
    //        assertEvents("didSave: " + uri);
    SwingUtilities.invokeLater(() -> {
        EditorApiPackageAccessor.get().forceRelease(pane);
    });
    assertEvents("didClose: " + uri);
    SwingUtilities.invokeLater(() -> {
        EditorApiPackageAccessor.get().register(pane);
    });
    assertEvents("didOpen: " + uri + "/" + MIME_TYPE + "/0/tet");
    SwingUtilities.invokeLater(() -> {
        EditorApiPackageAccessor.get().forceRelease(pane);
    });
    assertEvents("didClose: " + uri);
}

