public void testSimple() {
    List<Indexable> textPlains = Arrays.asList(new Indexable[] { SPIAccessor.getInstance().create(new TestIndexable("foo/indexable1", "text/plain")), SPIAccessor.getInstance().create(new TestIndexable("foo/indexable2", "text/plain")), SPIAccessor.getInstance().create(new TestIndexable("foo/indexable3", "text/plain")) });
    List<Indexable> javas = Arrays.asList(new Indexable[] { SPIAccessor.getInstance().create(new TestIndexable("java/indexable1", "text/x-java")), SPIAccessor.getInstance().create(new TestIndexable("java/indexable2", "text/x-java")) });
    List<Indexable> xmls = Arrays.asList(new Indexable[] { SPIAccessor.getInstance().create(new TestIndexable("xml/indexable1", "text/xml")), SPIAccessor.getInstance().create(new TestIndexable("xml/indexable2", "text/xml")), SPIAccessor.getInstance().create(new TestIndexable("xml/indexable3", "text/xml")), SPIAccessor.getInstance().create(new TestIndexable("xml/indexable4", "text/xml")), SPIAccessor.getInstance().create(new TestIndexable("xml/indexable5", "text/xml")) });
    List<Indexable> indexables = new ArrayList<Indexable>();
    indexables.addAll(textPlains);
    indexables.addAll(javas);
    indexables.addAll(xmls);
    Collections.shuffle(indexables);
    ClusteredIndexables ci = new ClusteredIndexables(indexables);
    // when asking for all mime types we should get everything
    List<Indexable> all = toList(ci.getIndexablesFor(null));
    check("Wrong all indexables", indexables, all);
    List<Indexable> tp = toList(ci.getIndexablesFor("text/plain"));
    check("Wrong text/plain indexables", textPlains, tp);
    List<Indexable> j = toList(ci.getIndexablesFor("text/x-java"));
    check("Wrong text/x-java indexables", javas, j);
    List<Indexable> x = toList(ci.getIndexablesFor("text/xml"));
    check("Wrong text/xml indexables", xmls, x);
    List<Indexable> allAgain = toList(ci.getIndexablesFor(null));
    check("Wrong all indexables", indexables, allAgain);
}

@Test
public void testRaceIssue222383() throws Exception {
    final ClusteredIndexables.AttachableDocumentIndexCache cache = ClusteredIndexables.createDocumentIndexCache();
    final ClusteredIndexables indexables1 = new ClusteredIndexables(Collections.<Indexable>emptyList());
    final ClusteredIndexables indexables2 = new ClusteredIndexables(Collections.<Indexable>emptyList());
    final CountDownLatch indexing = new CountDownLatch(1);
    final CountDownLatch changed = new CountDownLatch(1);
    final AtomicReference<Throwable> res = new AtomicReference<Throwable>();
    final Thread fastChangeThread = new Thread(new Runnable() {

        @Override
        public void run() {
            try {
                indexing.await();
            } catch (InterruptedException ex) {
                res.set(ex);
                return;
            }
            try {
                cache.attach(ClusteredIndexables.INDEX, indexables2);
                cache.detach();
            } catch (IllegalStateException e) {
                res.set(e);
            } finally {
                changed.countDown();
            }
        }
    });
    fastChangeThread.start();
    cache.attach(ClusteredIndexables.INDEX, indexables1);
    indexing.countDown();
    changed.await();
    //NOI18N
    Assert.assertEquals(indexables1, getCacheField(cache, "indexIndexables"));
    cache.detach();
    Assert.assertTrue(res.get() instanceof IllegalStateException);
}

@Test
public void testRaceIssue222383TransientUpdate() throws Exception {
    final ClusteredIndexables.AttachableDocumentIndexCache cache = ClusteredIndexables.createDocumentIndexCache();
    final ClusteredIndexables indexables1 = new ClusteredIndexables(Collections.<Indexable>emptyList());
    final ClusteredIndexables indexables2 = new ClusteredIndexables(Collections.<Indexable>emptyList());
    final CountDownLatch indexing = new CountDownLatch(1);
    final CountDownLatch changed = new CountDownLatch(1);
    final AtomicBoolean success = new AtomicBoolean();
    final Thread fastChangeThread = new Thread(new Runnable() {

        @Override
        public void run() {
            TransientUpdateSupport.setTransientUpdate(true);
            try {
                indexing.await();
                cache.attach(ClusteredIndexables.INDEX, indexables2);
                cache.detach();
                success.set(true);
            } catch (InterruptedException ioe) {
                //Ignore
            } finally {
                TransientUpdateSupport.setTransientUpdate(false);
                changed.countDown();
            }
        }
    });
    fastChangeThread.start();
    cache.attach(ClusteredIndexables.INDEX, indexables1);
    indexing.countDown();
    changed.await();
    //NOI18N
    Assert.assertEquals(indexables1, getCacheField(cache, "indexIndexables"));
    cache.detach();
    Assert.assertTrue(success.get());
}

@Test
public void testIndexAddDelete() throws Exception {
    for (int i = 0; i < 1000; i++) {
        IndexDocument docwrap = IndexManager.createDocument(Integer.toString(i));
        docwrap.addPair("bin", Integer.toBinaryString(i), true, true);
        docwrap.addPair("oct", Integer.toOctalString(i), true, true);
        index.addDocument(docwrap);
    }
    index.store(true);
    BitSet expected = new BitSet(1000);
    expected.set(0, 1000);
    assertIndex(expected);
    for (int i = 100; i < 200; i++) {
        index.removeDocument(Integer.toString(i));
        expected.clear(i);
    }
    index.store(true);
    assertIndex(expected);
}

@Test
public void testLRU() {
    final LRUCache<Integer, Evictable> ev = new LRUCache<Integer, Evictable>(new TestEvictionPolicy());
    final Set<Integer> golden = new HashSet<Integer>();
    for (int i = 0; i < 10; i++) {
        used.add(i);
        ev.put(i, new EvictableInt(i));
    }
    for (int i = 0; i < 5; i++) {
        used.add(i);
        golden.add(i);
        ev.put(i, new EvictableInt(i));
    }
    for (int i = 10; i < 15; i++) {
        used.add(i);
        golden.add(i);
        ev.put(i, new EvictableInt(i));
    }
    assertEquals(golden, used);
}

@Test
public void testRegexpStartText() throws Exception {
    // The first special char of the regexp ends the start text, in this
    // case a group is introduced
    assertEquals("base", getRegexpFilterPrefixForPattern("base(Query)"));
    // Quoted parts of the regexp are extracted verbatim
    assertEquals("base.*", getRegexpFilterPrefixForPattern(Pattern.quote("base.*")));
    // Quantifiers that can become 0 need to remove the character they work
    // on. Quantifiers on groups are handled by the group handling
    assertEquals("base", getRegexpFilterPrefixForPattern("base+"));
    assertEquals("bas", getRegexpFilterPrefixForPattern("base?"));
    assertEquals("bas", getRegexpFilterPrefixForPattern("base*"));
    assertEquals("bas", getRegexpFilterPrefixForPattern("base{0,5}"));
}

@Test
public void testChangesAreNotifiedWithoutHoldingALock() {
    Map<String, Object> data = new HashMap<>();
    data.put("service", String.class.getName());
    data.put("class", LazyLookupTest.class.getName());
    data.put("method", "testFactory");
    LazyLookup lkp = new LazyLookup(data, Lookup.EMPTY);
    class LL implements LookupListener {

        int cnt;

        @Override
        public void resultChanged(LookupEvent ev) {
            cnt++;
            assertFalse("Internal lock isn't held", lkp.isInitializing());
        }
    }
    LL listener = new LL();
    Lookup.Result<String> res = lkp.lookupResult(String.class);
    res.addLookupListener(listener);
    String value = lkp.lookup(String.class);
    assertEquals("Hello", value);
    assertEquals("One change", 1, listener.cnt);
}

