}

@Test
public void testValueReplacement() throws Exception {
    JTextField textField = new JTextField();
    BaseDocument doc = getDocument("/org/netbeans/modules/xml/text/completion/res/ValueReplacement.xml");
    BaseDocument referenceDoc = getDocument("/org/netbeans/modules/xml/text/completion/res/ValueReplacement.golden.xml");
    Finder ip1Finder = new FinderFactory.StringFwdFinder("##IP1##", true);
    int insertPos1 = doc.find(ip1Finder, doc.getStartPosition().getOffset(), doc.getEndPosition().getOffset());
    doc.replace(insertPos1, 7, "", null);
    textField.setDocument(doc);
    MockGrammarResult mgr = new MockGrammarResult("Middle", "Mid");
    ValueResultItem vri1 = new ValueResultItem(insertPos1, mgr, 0, null);
    textField.setCaretPosition(insertPos1);
    vri1.defaultAction(textField);
    Finder ip2Finder = new FinderFactory.StringFwdFinder("##IP2##", true);
    int insertPos2 = doc.find(ip2Finder, doc.getStartPosition().getOffset(), doc.getEndPosition().getOffset());
    doc.replace(insertPos2, 7, "", null);
    ValueResultItem vri2 = new ValueResultItem(insertPos2, mgr, 7, null);
    textField.setCaretPosition(insertPos2);
    vri2.defaultAction(textField);
    MockGrammarResult mgr2 = new MockGrammarResult("Middle", "");
    Finder ip3Finder = new FinderFactory.StringFwdFinder("##IP3##", true);
    int insertPos3 = doc.find(ip3Finder, doc.getStartPosition().getOffset(), doc.getEndPosition().getOffset());
    doc.replace(insertPos3, 7, "", null);
    ValueResultItem vri3 = new ValueResultItem(insertPos3, mgr2, 7, null);
    textField.setCaretPosition(insertPos3);
    vri3.defaultAction(textField);
    assertTrue("Result did not match reference", compare(referenceDoc, doc));
}

@Test
public void testShouldCloseTag() throws IOException, BadLocationException, Exception {
    BaseDocument doc = getDocument("/org/netbeans/modules/xml/text/completion/res/docResourceUnclosed.html");
    XMLSyntaxSupport xss = XMLSyntaxSupport.getSyntaxSupport((BaseDocument) doc);
    // ##IP1## and ##IP2## mark the positions in the document
    // which will be checked fif at that point the tag should be closed
    Finder ip1Finder = new FinderFactory.StringFwdFinder("##IP1##", true);
    Finder ip2Finder = new FinderFactory.StringFwdFinder("##IP2##", true);
    int insertPos1 = doc.find(ip1Finder, doc.getStartPosition().getOffset(), doc.getEndPosition().getOffset());
    int insertPos2 = doc.find(ip2Finder, doc.getStartPosition().getOffset(), doc.getEndPosition().getOffset());
    // The first position is a caret position behind a <a> Element, that
    // has a closing tag => shouldCloseTag needs to return NULL here to
    // indicate, that inserted content should be inserted without the
    // closing tag.
    SyntaxQueryHelper sqh = new SyntaxQueryHelper(xss, insertPos1);
    assertNull("XMLCompletionQuery#shouldCloseTag should return NULL if closing tag is present", XMLCompletionQuery.shouldCloseTag(sqh, doc, xss));
    // The second position is a caret position behind a <a> Element without
    // a matching end tag.
    SyntaxQueryHelper sqh2 = new SyntaxQueryHelper(xss, insertPos2);
    assertEquals("XMLCompletionQuery#shouldCloseTag should return tagname if no closing tag is present", "a", XMLCompletionQuery.shouldCloseTag(sqh2, doc, xss));
}

@Test
public void testArgumentFiles() throws Exception {
    FileObject wd = FileUtil.toFileObject(getWorkDir());
    FileObject argfile = FileUtil.createData(wd, "argfile");
    try (OutputStream out = argfile.getOutputStream()) {
        out.write("test \t\t \"quoted1\"   'quoted2'\n   \t\n   @argfile\n".getBytes(StandardCharsets.UTF_8));
    }
    assertEquals(Arrays.asList("test", "quoted1", "quoted2", "@argfile"), Result.doParseLine("@argfile", wd.toURI()));
