    assertEquals(Arrays.asList("@"), Result.doParseLine("@", wd.toURI()));
    assertEquals(Arrays.asList("test", "quoted1", "quoted2", "@argfile"), Result.doParseLine("@" + FileUtil.toFile(argfile).getAbsolutePath(), wd.toURI()));
