@Test
public void testClassToString() throws IOException {
    clearWorkDir();
    final File testRoot = getTestRoot();
    if (testRoot == null) {
        System.err.println("No test root.");
        return;
    }
    final Path from = testRoot.toPath();
    Files.walk(from).filter(new Predicate<Path>() {

        @Override
        public boolean test(Path p) {
            return Files.isRegularFile(p) && p.getName(p.getNameCount() - 1).toString().endsWith(".class") && //NOI18N
            !p.getName(p.getNameCount() - 1).toString().contains("$");
        }
    }).limit(1).forEach(new Consumer<Path>() {

        @Override
        public void accept(Path p) {
            try {
                System.out.println(p);
                try (InputStream in = Files.newInputStream(p)) {
                    final ClassFile cf = new ClassFile(in);
                    System.out.println(cf);
                }
            } catch (IOException ioe) {
                throw new RuntimeException(ioe);
            }
        }
    });
}

