    assertEquals(1, res.size());
    Map.Entry<String, byte[]> e = res.entrySet().iterator().next();
    //NOI18N
    assertEquals("nb.A", e.getKey());
    final ClassFile cf = new ClassFile(new ByteArrayInputStream(e.getValue()));
    assertEquals(2, cf.getMethodCount());
    final Set<String> methods = cf.getMethods().stream().map((m) -> m.getName()).collect(Collectors.toSet());
    assertEquals(new HashSet<>(Arrays.asList(new String[] { //NOI18N
    "<init>", //NOI18N
