@Test
@SuppressWarnings("ThrowableResultIgnored")
public void testSelectAppropriateHandler() throws URISyntaxException, InterruptedException, ExecutionException {
    Future<Object> x0 = new Intent("NONE", new URI("unsupported://resource")).execute();
    Exception e = null;
    try {
        x0.get();
    } catch (InterruptedException | ExecutionException ex) {
        e = ex;
    }
    assertTrue(e instanceof ExecutionException && (e.getCause() instanceof NoAvailableHandlerException));
    Future<Object> x1 = new Intent("NONE", new URI("broken://resource")).execute();
    try {
