@Test
public void testMatchType() {
    assertFalse("Literal match type shoudn't be a regexp pattern", SearchPattern.create("test", false, false, MatchType.LITERAL).isRegExp());
    assertFalse("Basic match type shoudn't be a regexp pattern", SearchPattern.create("test", false, false, MatchType.BASIC).isRegExp());
    assertTrue("Regexp match type should be a regexp pattern", SearchPattern.create("test", false, false, MatchType.REGEXP).isRegExp());
    assertTrue("Chaning match type to REGEXP should create regexp pattern", SearchPattern.create("test", false, false, MatchType.LITERAL).changeMatchType(MatchType.REGEXP).isRegExp());
    assertEquals("Changing match type to LITERAL should work", MatchType.LITERAL, SearchPattern.create("test", false, false, true).changeMatchType(MatchType.LITERAL).getMatchType());
    assertEquals("Chaning match type to BASIC should work", MatchType.BASIC, SearchPattern.create("test", false, false, true).changeMatchType(MatchType.BASIC).getMatchType());
    assertEquals("If not specified exactly, match type should be LITERAL", MatchType.LITERAL, SearchPattern.create("test", false, false, false).getMatchType());
}

@Test
public void testBindComboBox() {
    JComboBox<?> cb = new JComboBox<>();
    SearchPatternController controller = ComponentUtils.adjustComboForSearchPattern(cb);
    JComboBox<MatchType> matchTypeCb = new JComboBox<>(new MatchType[] { MatchType.BASIC, MatchType.LITERAL, MatchType.REGEXP });
    assertEquals(MatchType.BASIC, matchTypeCb.getSelectedItem());
    controller.bindMatchTypeComboBox(matchTypeCb);
    boolean thrown = false;
    try {
        controller.bindMatchTypeComboBox(matchTypeCb);
    } catch (Exception e) {
        thrown = true;
    }
    assertTrue("Exception should be thrown when trying to bind " + "a property twice", thrown);
    controller.setSearchPattern(SearchPattern.create("test", false, false, MatchType.LITERAL));
    assertEquals(MatchType.LITERAL, matchTypeCb.getSelectedItem());
    controller.setSearchPattern(SearchPattern.create("test", false, false, MatchType.REGEXP));
    assertEquals(MatchType.REGEXP, matchTypeCb.getSelectedItem());
    controller.setSearchPattern(SearchPattern.create("test", false, false, MatchType.BASIC));
    assertEquals(MatchType.BASIC, matchTypeCb.getSelectedItem());
    matchTypeCb.setSelectedItem(MatchType.LITERAL);
    assertEquals(MatchType.LITERAL, controller.getSearchPattern().getMatchType());
    matchTypeCb.setSelectedItem(MatchType.REGEXP);
    assertEquals(MatchType.REGEXP, controller.getSearchPattern().getMatchType());
    matchTypeCb.setSelectedItem(MatchType.BASIC);
    assertEquals(MatchType.BASIC, controller.getSearchPattern().getMatchType());
}

