/**
 * Test for bug 244044.
 *
 * @throws java.io.IOException
 */
@Test
public void testDeadlock244044() throws IOException {
    final ResultModel rm = SearchTestUtils.createResultModelWithSampleData(false);
    final ResultsOutlineSupport[] ros = new ResultsOutlineSupport[1];
    try {
        EventQueue.invokeAndWait(() -> ros[0] = new ResultsOutlineSupport(false, false, rm, null, Node.EMPTY));
    } catch (InterruptedException | InvocationTargetException ex) {
        Exceptions.printStackTrace(ex);
    }
    assertNotNull(ros[0]);
    final FileSystem fs = FileUtil.createMemoryFileSystem();
    @SuppressWarnings("PackageVisibleField")
    class FinishFlag {

        volatile boolean thread1Finished = false;

        volatile boolean thread2Finished = false;

        boolean areThreadsFinished() {
            return thread1Finished && thread2Finished;
        }
    }
    for (int i = 0; i < 100; i++) {
        final int fi = i;
        final FinishFlag finishFlag = new FinishFlag();
        final String fileName = "file" + fi + ".txt";
        try {
            fs.getRoot().createData(fileName);
            rm.objectFound(fs.getRoot().getFileObject(fileName), Charset.defaultCharset(), null);
        } catch (IOException ex) {
            Exceptions.printStackTrace(ex);
        }
        // Add a new file ...
        Thread t1 = new Thread(() -> {
            ros[0].update();
            ros[0].getResultsNode().getChildren().getNodes();
            finishFlag.thread1Finished = true;
        });
        // ... and close the model at the same time.
        Thread t2 = new Thread(() -> {
            // simulate ResultsOutlineSupport.clean() - synchronize and
            // call ResultModel.close()
            synchronized (ros[0]) {
                rm.close();
                ros[0].getResultsNode().getChildren().getNodes();
            }
            finishFlag.thread2Finished = true;
        });
        t1.start();
        t2.start();
        try {
            t1.join(10000);
            t2.join(10000);
        } catch (InterruptedException ex) {
            Exceptions.printStackTrace(ex);
        }
        if (!finishFlag.areThreadsFinished()) {
            fail("Deadlock occured at iteration " + fi);
        }
    }
}

/**
 * Bug 233192 - java.util.ConcurrentModificationException at
 * java.util.ArrayList$Itr.checkForComodification.
 *
 * @throws java.lang.InterruptedException
 */
@Test
public void testThreadSafe() throws InterruptedException {
    final Semaphore semaphoreAddExtraListener = new Semaphore(0);
    final Semaphore semaphoreContinueIterating = new Semaphore(0);
    final MySSDefinition mssd = new MySSDefinition();
    // Count notified listeners.
    final int[] notified = new int[1];
    // Add listeners. After the first listener is notified, a new listener
    // can be added from another thread. Then, the second listener can be
    // notified.
    for (int i = 0; i < 10; i++) {
        final int j = i;
        mssd.addChangeListener((ChangeEvent e) -> {
            if (j == 0) {
                // allow the new listener to be added
                semaphoreAddExtraListener.release();
            } else if (j == 1) {
                try {
                    // wait until the new listener added
                    semaphoreContinueIterating.acquire();
                } catch (InterruptedException ex) {
                    Exceptions.printStackTrace(ex);
                }
            }
            notified[0]++;
        });
    }
    // Thead that adds a new listener while the listener list is being
    // iterated over.
    Thread t1 = new Thread(() -> {
        try {
            // wait until listeners are iterated
            semaphoreAddExtraListener.acquire();
        } catch (InterruptedException ex) {
            Exceptions.printStackTrace(ex);
        }
        mssd.addChangeListener((ChangeEvent e) -> {
        });
        // the iteration can continue
        semaphoreContinueIterating.release();
    });
    t1.start();
    mssd.runNotifyListeners();
    t1.join();
    assertEquals("All listeners should be notified", 10, notified[0]);
}

