/**
 * Test for bug 235928 - Deadlock scanning after change name of project with
 * folder.
 *
 * @throws java.io.IOException
 * @throws java.lang.InterruptedException
 */
@Test
public void testBug235928() throws IOException, InterruptedException {
    final Semaphore s = new Semaphore(0);
    /**
     * Listener that enables running of thread t2 while the events are
     * processed in the main thread.
     */
    final FileChangeListener fcl = new FileChangeAdapter() {

        @Override
        public void fileFolderCreated(FileEvent fe) {
            // Thread t2 can run.
            s.release();
            try {
                // Wait until thread t2 is finished.
                s.acquire(2);
            } catch (InterruptedException ex) {
                Exceptions.printStackTrace(ex);
            }
        }
    };
    Thread t2 = new Thread(new Runnable() {

        @Override
        public void run() {
            FileChangeListener l = new FileChangeAdapter();
            try {
                s.acquire();
                // Try to add a listener, to ensure that the keeper object
                // is not locked.
                workDirFO.addRecursiveListener(l);
                s.release(2);
            } catch (InterruptedException ex) {
                Exceptions.printStackTrace(ex);
            } finally {
                workDirFO.removeRecursiveListener(l);
            }
        }
    });
    workDirFO.addRecursiveListener(fcl);
    try {
        t2.start();
        // Create folder and process events.
        workDirFO.createFolder("test");
        t2.join();
    } finally {
        workDirFO.removeRecursiveListener(fcl);
    }
}

@Test
public void testDeadlockWhenNotifierCallsSecurityManager() throws InterruptedException {
    // permits - progress
    // 1 - Priority IO can enter priority section (lock taken by idle IO)
    // 2 - Idle IO can ask for some IO operation (security manager blocked)
    Semaphore s = new Semaphore(0);
    Lookup.getDefault().lookup(MockNotifier.class).setSemaphore(s);
    IdleIO idleIO = new IdleIO(s);
    PriorityIO priorityIO = new PriorityIO(s);
    // Thread 1 - Enter idleIO, add a watch -> wait for priority
    Thread idle = new Thread(idleIO, "Idle IO Thread");
    // Thread 2 - Enter priority IO, wait for watch's lock.
    Thread priority = new Thread(priorityIO, "Priority IO Thread");
    idle.start();
    priority.start();
    idle.join(2000);
    priority.join(2000);
    assertTrue("Idle IO should be finished", idleIO.finished.get());
    assertTrue("Priority IO should be finished", priorityIO.finished.get());
}

