@Test
public void taksIsNotFinished_untilRunMethodCompletes() throws Exception {
    Object lock = new Object();
    Task task = new Task(() -> {
        synchronized (lock) {
            // let the test thread continue
            lock.notify();
            try {
                lock.wait();
            } catch (InterruptedException e) {
                fail("This shall never happen as the test does not call 'interrupt()'.");
            }
        }
    });
    assertFalse("Task should not have been finished.", task.isFinished());
    synchronized (lock) {
        new Thread(task).start();
        // wait for task to start
        lock.wait();
    }
    assertFalse("Task should not have been finished.", task.isFinished());
    synchronized (lock) {
        //let the task finish
        lock.notify();
    }
    task.waitFinished();
    assertTrue("Task should have finished.", task.isFinished());
}

