    f.setAccessible(true);
    WizardDescriptor.Iterator<?> master = (WizardDescriptor.Iterator<?>) f.get(tw);
    assertNotNull("Master iterator found", master);
    WizardDescriptor.Panel<?> p1 = master.current();
    assertNotNull("Panel found", p1);
