    String[] lines = { "regex = "1.7.1"                    # An implementation of regular expressions for Rust. This implementation uses finite automata …
", "lazy-regex = "2.4.1"               # lazy static regular expressions checked at compile time
", "proc-macro-regex = "1.1.0"         # A proc macro regex library
", "regex-automata = "0.2.0"           # Automata construction and matching using regular expressions.
", "easy-regex = "0.11.7"              # Make long regular expressions like pseudocodes
", "readable-regex = "0.1.0-alpha1"    # Regex made for humans. Wrapper to build regexes in a verbose style.
", "human_regex = "0.2.3"              # A regex library for humans
", "regex_static = "0.1.1"             # Compile-time validated regex, with convenience functions for lazy and static regexes.
", "webforms = "0.2.2"                 # Provides form validation for web forms
", "hashtag-regex = "0.1.1"            # A simple regex matching hashtags accoding to the unicode spec: http://unicode.org/reports/tr…
", "safe-regex = "0.2.5"               # Safe regular expression library
", "pleaser = "0.5.4"                  # please, a polite regex-first sudo alternative
", "rand_regex = "0.15.1"              # Generates random strings and byte strings matching a regex
", "regex-macro = "0.2.0"              # A macro to generate a lazy regex expression
", "regex-syntax = "0.6.28"            # A regular expression parser.
", "... and 930 crates more (use --limit N to see more)" };
    // ... when we filter them...
    List<RustPackage> packages = CargoBuildImpl.filterLines(null, Arrays.asList(lines));
    // .. then 15 packages should have been detected
    Assert.assertEquals(15, packages.size());
}

@Test
public void testShouldDetectHyperlinks() throws Exception {
    System.out.println("testShouldDetectHyperlinks");
    // Given some error lines with a proper source position
    String[] lines = { " --> src/main.rs:8:17", "  --> src/main.rs:17:12", "  --> src/main.rs:29:8" };
    for (String line : lines) {
        // When we try to find the position
        Matcher matcher = RustErrorHyperlinkConvertorFactory.matchesSourcePosition(line);
        // Then the position is found
        assertTrue("This line could not be detected: " + line, matcher.matches());
        assertEquals("src/main.rs", matcher.group(1));
        int nLine = Integer.parseInt(matcher.group(2));
        assertEquals("" + nLine, matcher.group(2));
        int nCol = Integer.parseInt(matcher.group(3));
        assertEquals("" + nCol, matcher.group(3));
    }
}

